insert into _k1_trivia values ('apothecary-diaries', 'series', 'apothecary-diaries', 'The Apothecary Diaries is Kusuriya no Hitorigoto in Japanese, a title that can be read as Apothecary''s Soliloquy.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Hyūganatsu is the author of the story, and Touko Shino draws the illustrations of the published light novels.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'The tale began as a web novel on Shōsetsuka ni Narō in 2011, then Shufunotomo issued a single book in 2012 and a Hero Bunko light novel line from August 29, 2014, which had 16 volumes by May 2025.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Square Enix publishes the first manga adaptation, drawn by Nekokurage, in Monthly Big Gangan; it started on May 25, 2017 and has reached 17 volumes.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'A second manga take, drawn by Minoji Kurata for Shogakukan''s Monthly Sunday Gene-X, launched on August 19, 2017 under the title Maomao''s Notes on the Inner Palace.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Toho Animation Studio and OLM made the first season together, and its 24 episodes ran on Nippon TV from October 22, 2023 until March 24, 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Season two returned on January 10, 2025 and ended on July 4, 2025, adding episodes 25 to 48 to the total of 48.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'The story takes place in an invented empire modeled on Tang-era China, although the author points out that it is technically not set in China.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Counting the light novels and both manga series, the franchise had more than 57 million copies in circulation by August 2026.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/The_Apothecary_Diaries', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Season one started with Hana ni Natte and Aikotoba, then switched to Ambivalent by Uru and Ai wa Kusuri by Wacci.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Season two opened with Hyakka Ryōran by Lilas Ikuta and later Kusushiki by Mrs. Green Apple, with Dai Hirai and Omoinotake singing the endings.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'The third season pairs an opening by Yorushika with the ending song AIYOU by Eve.', 'music', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'No source names story arcs, so this quiz follows the three anime seasons, with the third still on air in October 2026.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_episodes', 'published'), ('apothecary-diaries', 'character', 'maomao', 'Maomao is a main character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'jinshi', 'Jinshi is a main character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'gaoshun', 'Gaoshun is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'gyokuyo', 'Gyokuyō is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lihua', 'Lihua is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lishu', 'Lishu is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'ah-duo', 'Ah-Duo is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lakan', 'Lakan is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lihaku', 'Lihaku is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'xiaolan', 'Xiaolan is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'basen', 'Basen is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'luomen', 'Luomen is a supporting character of The Apothecary Diaries.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'gyokuyo', 'Gyokuyō makes her home in the Jade Pavilion, a residence inside the Rear Palace.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'gyokuyo', 'Gyokuyō hires Maomao as a lady-in-waiting after Maomao warns her that her makeup is poisoned.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lishu', 'Lishu lives in the Diamond Pavilion, which sits in the Rear Palace.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lishu', 'Lishu suffers from food allergies, yet her attendants take it for fussy eating.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'maomao', 'Maomao grew up in the Verdigris House, a well-known brothel in the capital.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'The Three Princesses are the best-known courtesans of the Verdigris House, and they helped raise Maomao.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'An old woman, known as the Madam, owns the Verdigris House and gave Maomao a place to work there.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Guen serves as the palace doctor, though Maomao regards him as a quack.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Guen comes from a family that supplies the palace with fine paper.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'gyokuyo', 'Gyokuyō, the Precious Consort, holds the place of the emperor''s favourite among his four top-ranking consorts.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'series', 'apothecary-diaries', 'Hongniang runs the staff of the Jade Pavilion as its head lady-in-waiting and is a decent boss to Maomao.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('apothecary-diaries', 'character', 'lishu', 'Lishu, the Virtuous Consort, is the youngest of the emperor''s four top-ranking consorts.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_The_Apothecary_Diaries_characters', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'Episode titles of the last season echo manga chapter titles, which shows where each part stops: Part 1 ends at chapter 116 and Part 2 at chapter 130.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_chapters', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'Attack on Titan carries the Japanese title 進撃の巨人, read Shingeki no Kyojin, which translates roughly as The Advancing Giant.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'Hajime Isayama wrote and drew the whole manga himself.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The manga appeared in monthly installments from September 2009 until its finale in April 2021.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'It ran in Kodansha''s monthly Bessatsu Shōnen Magazine, which launched with the first chapter.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The chapters were collected in 34 volumes, and the story closed after 139 chapters.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The finale was chapter number 139.', 'history', 'wikipedia', 'https://ja.wikipedia.org/wiki/%E9%80%B2%E6%92%83%E3%81%AE%E5%B7%A8%E4%BA%BA', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The anime opened on 7 April 2013 with a 25-episode first season.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'Tetsurō Araki directed the first three seasons, and Yuichiro Hayashi directed the fourth.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The anime reached its last broadcast on 5 November 2023, with the second Final Chapters special.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'Only two other manga have matched the first print of volume 12, which topped two million copies.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The manga won the Kodansha Manga Award for best shonen title in 2011.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'The show once held a Guinness record for demand among anime series, and later lost the broader animated-TV title to another series in 2024.', 'achievements', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)', 'published'), ('attack-on-titan', 'series', 'attack-on-titan', 'A compilation film of the finale, titled The Last Attack, arrived in Japan on 8 November 2024.', 'history', 'wikipedia', 'https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)', 'published'), ('attack-on-titan', 'character', 'eren-yeager', 'Eren''s Titan form was drawn after a real middleweight mixed martial artist, Yushin Okami.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'jean-kirstein', 'When asked to name his favourite character, the author picked Jean for saying what he really thinks.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'levi-ackerman', 'Levi''s look and manner were modeled on Rorschach, a character from the comic Watchmen.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'eren-yeager', 'Eren''s Titan form is called the Attack Titan, whose Japanese name is the same as the title of the series.', 'fun', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'eren-yeager', 'Eren Yeager is a main character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'mikasa-ackerman', 'Mikasa Ackerman is a main character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'armin-arlert', 'Armin Arlert is a main character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'levi-ackerman', 'Levi Ackerman is a main character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'erwin-smith', 'Erwin Smith is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'hange-zoe', 'Hange Zoë is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'jean-kirstein', 'Jean Kirstein is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'connie-springer', 'Connie Springer is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'sasha-blouse', 'Sasha Blouse is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_characters', 'published'), ('attack-on-titan', 'character', 'krista-lenz', 'Krista Lenz is a supporting character of Attack on Titan.', 'members', 'wikipedia', 'https://en.wikipedia.org/wiki/List_of_Attack_on_Titan_charact